-- ============================================================
-- VAY PERFUME — перенос текущего каталога (SEED_FRAGRANCES) и
-- отзывов (SEED_REVIEWS) из script.js в Supabase.
-- Выполнить ОДИН РАЗ, после schema.sql, в SQL Editor.
-- Повторный запуск безопасен: строки с тем же id обновятся (upsert).
--
-- image_url ниже указывает на файлы *.jpg из корня текущего сайта.
-- Пока фото не загружены отдельно в Supabase Storage, публичный
-- сайт продолжит показывать их из корня проекта — это
-- нормально, замена на Storage-ссылки происходит через админку
-- (при загрузке нового фото для товара).
-- ============================================================

on conflict (id) do update set
  name = excluded.name, brand = excluded.brand, category = excluded.category,
  volume = excluded.volume, price = excluded.price, old_price = excluded.old_price,
  feel = excluded.feel, notes_top = excluded.notes_top, notes_heart = excluded.notes_heart,
  notes_base = excluded.notes_base, character = excluded.character, type = excluded.type,
  in_stock = excluded.in_stock, image_url = excluded.image_url, sort_order = excluded.sort_order;

on conflict (id) do update set
  image_url = excluded.image_url, alt = excluded.alt, sort_order = excluded.sort_order;

;