insert into fragrances
  (id, name, brand, category, volume, price, old_price, feel, notes_top, notes_heart, notes_base, character, type, in_stock, image_url, sort_order, is_visible)
values
  ('him-01', 'Sehr', 'Lattafa', 'him', '100 мл', '3 500 ₽', '', 'Тёплый, пряно-сладкий аромат с мягким миндальным оттенком. Уютный вечер, где пряная корица постепенно становится нежнее, а сладкая ваниль и тёплая амбра создают мягкое, глубокое и немного чувственное звучание. Для тех, кто хочет тепла и заметности без приторной сладости. Подойдёт и ему, и ей.', 'Корица, горький миндаль', 'Жасмин, Pomarose, Akigalawood, ваниль', 'Абсолют ванили, амбра, бобы тонка', '', '', true, 'him-01.jpg', 0, true),
  ('him-02', 'Opulent Shaik Sapphire', 'Designer Shaik Arabia', 'him', '100 мл', '3 500 ₽', '', 'Насыщенный, пряно-свежий аромат с ощущением дорогой классики. Сначала звучит ярко и свежо, затем раскрывается тёплыми специями и яблоком, а со временем становится глубже, мягче и древеснее. Для тех, кто хочет аромат с характером — заметный, элегантный и не похожий на обычную свежесть. Подойдёт мужчинам, которые любят выразительные и благородные ароматы.', 'Бергамот, лимон, лаванда, базилик', 'Яблоко, корица, гвоздика, герань', 'Кедр, дубовый мох, пачули, лабданум, ваниль, мускус', '', '', true, 'him-02.jpg', 1, true),
  ('him-03', 'Qaed Al Fursan Untamed', 'Lattafa', 'him', '90 мл', '2 500 ₽', '', 'Тёплый, пряный и выразительный аромат с лёгкой свежестью мандарина. Сочетание согревающих специй, свежей лаванды и мягкой карамели — сначала звучит ярко и пряно, затем становится глубже, теплее и древеснее. Для тех, кто хочет аромат с характером, уверенный и заметный, но без тяжёлой сладости. Подойдёт и ему, и ей, особенно тем, кто любит тёплые пряно-древесные композиции.', 'Мускатный орех, кардамон, мандарин, корица', 'Лаванда, герань, кипарис, мускатный шалфей, карамель', 'Кедр, олибанум, ветивер, лабданум, амбра', '', '', true, 'him-03.jpg', 2, true),
  ('him-04', 'Khamrah Qahwa', 'Lattafa', 'him', '100 мл', '3 500 ₽', '', 'Тёплый, сладкий и пряный аромат с красивым кофейным акцентом. Чашка свежесваренного кофе рядом с ванильным десертом: сначала раскрывается пряной корицей, имбирём и кардамоном, затем становится мягким, сладким и уютным. Для тех, кто хочет насыщенный аромат с настоящим ощущением кофе, тепла и сладости. Подойдёт и ему, и ей, особенно если нравятся гурманские ароматы.', 'Имбирь, корица, кардамон', 'Пралине, засахаренные фрукты, белые цветы', 'Кофе Arabica, бобы тонка, мускус, бензоин, ваниль', '', '', true, 'him-04.jpg', 3, true),
  ('him-05', 'Veneno', 'French Avenue', 'him', '100 мл', '2 600 ₽', '', 'Тёмный, пряный и немного дымный аромат с сочным яблочным оттенком. Тёплое пряное яблоко, окутанное лёгким дымом и табачными нотами — постепенно становится глубже, мягче и теплее благодаря ванили. Для тех, кто хочет что-то выразительное, необычное и с характером. Подойдёт и ему, и ей, особенно если нравятся пряные, дымные и слегка сладковатые ароматы.', 'Яблоко, корица, дым', 'Табак, мох', 'Бурбонская ваниль, Orcanox', '', '', true, 'him-05.jpg', 4, true),
  ('him-06', 'Liquid Brun', 'French Avenue', 'him', '100 мл', '3 500 ₽', '4 000 ₽', 'Тёплый, сладкий и пряный аромат с кремовой ванилью и лёгким цитрусовым оттенком. Свежий воздух с ароматом корицы и кардамона, а затем мягкая ваниль, сладкое пралине и тёплые древесные ноты. Постепенно становится глубже и уютнее, оставляя сладковатый, ванильный и слегка древесный шлейф — особенно хорошо раскрывается в прохладную погоду и вечером. Для тех, кто любит тёплые сладкие ароматы с ванилью и специями.', 'Корица, бергамот, кардамон, цветок апельсина', 'Бурбонская ваниль, элеми', 'Мускус, пралине, амброксан, гваяковое дерево', '', '', true, 'him-06.jpg', 5, true),
  ('him-07', 'Amber Empire', 'French Avenue', 'him', '100 мл', '3 500 ₽', '', 'Тёплый, насыщенный и элегантный аромат с мягкой ванилью, тёплой амброй и древесными нотами. Сладковато-пряный аромат, в котором ваниль и лёгкая ликёрная нота постепенно переходят в тёплую амбру, кедр и мягкое сандаловое дерево. В раскрытии становится глубже и спокойнее, оставляя тёплый, слегка сладкий и древесный шлейф. Для тех, кто хочет выразительный аромат с ощущением тепла, дорогой древесины и мягкой сладости.', 'Ваниль, кашемировое дерево, восточные ноты, ликёр', 'Амбра, тростниковый сахар, кедр', 'Бобы тонка, лабданум, сандаловое дерево, мускус', '', '', true, 'him-07.jpg', 6, true),
  ('him-08', 'Ameer Al Arab', 'Asdaaf', 'him', '100 мл', '2 500 ₽', '', 'Свежий, пряный и немного восточный аромат с красивым сочетанием цветов, специй и зелёных нот. В начале ощущается мягкая сладость жасмина и жимолости, затем появляются лаванда, шафран и перец, а в базе — прохладная мята, кардамон и базилик. В итоге аромат получается свежим, пряным и чистым, с заметным восточным характером, но без тяжёлой сладости. Для тех, кто хочет универсальный аромат на каждый день, который звучит ухоженно, свежо и с характером.', 'Жасмин, жимолость', 'Лаванда, шафран, перец', 'Мята, кардамон, базилик', '', '', true, 'him-08.jpg', 7, true),
  ('him-09', 'Qaed Al Fursan Unlimited', 'Lattafa', 'him', '90 мл', '2 500 ₽', '', 'Сладкий, кремовый и тропический аромат с сочным ананасом и мягким кокосом. Прохладный тропический напиток с фруктами и кокосовыми сливками — постепенно добавляются нежные белые цветы, а в базе остаются ваниль, мускус и мягкое сандаловое дерево. Лёгкий, солнечный и уютный, без тяжёлой приторности. Хороший вариант, если хочется чего-то сладкого, свежего и немного отпускного по настроению. Подойдёт и ему, и ей.', 'Ананас, цитрусы, кокос', 'Жасмин, франжипани, иланг-иланг', 'Ваниль, белый мускус, сандаловое дерево, сладкие ноты', '', '', true, 'him-09.jpg', 8, true),
  ('him-10', 'Saheb Intense', 'Ard Al Zaafaran', 'him', '70 мл', '2 900 ₽', '3 500 ₽', 'Свежий, цитрусовый и пряный аромат с лёгкой чайной глубиной. В начале звучит ярко и свежо благодаря цитрусам, бергамоту и апельсину, затем появляются имбирь, нероли и тёплая корица. Постепенно становится спокойнее и глубже — к свежести добавляются чёрный чай, древесные и слегка дымные оттенки. Для тех, кто хочет свежий аромат, но не совсем обычную «свежесть», а с пряным характером и интересным шлейфом. Подойдёт и ему, и ей.', 'Цитрон, калабрийский бергамот, сицилийский апельсин', 'Тунисский нероли, нигерийский имбирь, цейлонская корица', 'Чёрный чай, амброксан, гваяковое дерево, ладан', '', '', true, 'him-10.jpg', 9, true),
  ('him-11', 'Amber Oud Aqua Dubai', 'Al Haramain', 'him', '75 мл', '7 500 ₽', '8 500 ₽', 'Свежий, сочный и лёгкий аромат с ярким цитрусовым стартом и тропическими фруктами. Прохладный фруктовый напиток: сначала ощущаются бергамот, мандарин и свежие зелёные ноты, затем раскрываются сочная дыня, ананас, чёрная смородина и мягкая амбра. В конце становится спокойнее и мягче — появляется ваниль, мускус и лёгкая зелёная глубина. Для тех, кто хочет свежий, современный и заметный аромат на каждый день, особенно для тёплой погоды. Подойдёт и ему, и ей.', 'Бергамот, мандарин, зелёные ноты', 'Дыня, ананас, амбра, чёрная смородина', 'Мускус, ваниль, гальбанум, петитгрейн', '', '', true, 'him-11.jpg', 10, true),
  ('him-12', 'Megara', 'Maison Alhambra', 'him', '50 мл', '4 000 ₽', '', 'Свежий, морской и очень прохладный аромат с яркими цитрусами. Свежий воздух у моря: сначала ощущаются сочный лимон и бергамот, затем появляется влажная морская свежесть с оттенком водорослей, а в базе остаются мягкие древесные и мускусные ноты. Заметный, прохладный и немного солоноватый — совсем не про сладость. Хороший вариант, если хочется ощущения чистоты, свежего воздуха и моря. Подойдёт и ему, и ей.', 'Бергамот, лимон', 'Морские водоросли, Calone, Hedione', 'Амброксан, мускус, кедр', '', '', true, 'him-12.jpg', 11, true),
  ('him-13', 'Pisa', 'Lattafa Pride', 'him', '100 мл', '4 500 ₽', '', 'Свежий, сочный и чистый аромат с ярким цитрусовым началом. Свежесрезанный мандарин, лимон и бергамот — звучит солнечно, легко и очень бодро. Постепенно цитрусовая свежесть становится спокойнее, появляются суховатые древесные оттенки кедра, а в финале аромат становится мягче и теплее благодаря сандалу и амбре. Для тех, кто хочет свежий, ухоженный и современный аромат без сладости на каждый день.', 'Мандарин, лимон, бергамот', 'Кедр', 'Сандаловое дерево, амбра', '', '', true, 'him-13.jpg', 12, true),
  ('him-14', 'Qaed Al Fursan', 'Lattafa', 'him', '90 мл', '2 500 ₽', '', 'Сочный, сладковато-фруктовый аромат с ярким ананасом и тёплыми пряными оттенками шафрана. Спелый тропический ананас с лёгкой пряностью — постепенно добавляются жасмин и мягкие бальзамические ноты, а в базе остаются тёплая амбра, кедр и уд. Фруктовый, насыщенный и слегка древесный, с заметным восточным характером. Для тех, кто хочет сладкий, сочный и выразительный аромат с ананасом. Подойдёт и ему, и ей.', 'Ананас, шафран', 'Жасмин, пихтовый бальзам', 'Уд, кедр, амбра', '', '', true, 'him-14.jpg', 13, true),
  ('him-15', 'Now', 'RAVE', 'him', '100 мл', '2 500 ₽', '', 'Сочный, фруктовый и немного древесный аромат с ярким ананасом. Спелый сочный ананас с яблоком и чёрной смородиной — начало свежее, сладковатое и очень заметное. Постепенно фруктовая свежесть сменяется более глубоким звучанием: появляются сухие древесные оттенки берёзы, роза, жасмин и пачули, а в базе остаются мягкая ваниль, мускус, мох и тёплая амбра. Для тех, кто любит фруктовые ароматы с характером, особенно с ярким ананасом и древесной базой.', 'Ананас, чёрная смородина, бергамот, яблоко', 'Роза, сухая берёза, марокканский жасмин, пачули', 'Мускус, ваниль, дубовый мох, амбра', '', '', true, 'him-15.jpg', 14, true),
  ('her-01', 'Veneno Bianco', 'French Avenue', 'her', '100 мл', '2 600 ₽', '3 000 ₽', 'Нежный, кремовый и солнечный аромат с молочным акцентом, белыми цветами и кокосом. Тёплый день у моря: сначала звучат свежие бергамот и нероли, затем раскрываются нежные цветы тиаре, иланг-иланг и белые цветы. Постепенно становится мягким и тёплым — появляется кокос, ваниль и лёгкие древесно-амбровые оттенки. Ощущение кремового, цветочного и немного тропического аромата. Для тех, кто хочет что-то нежное, женственное и с ощущением тёплой кожи, солнца и отпуска.', 'Бергамот, нероли, молоко', 'Цветок тиаре, иланг-иланг, белые цветы', 'Кокос, ваниль, гваяковое дерево, лабданум', '', '', true, 'her-01.jpg', 15, true),
  ('her-02', 'Blush Noire', 'Ahmed Al Maghribi', 'her', '75 мл', '3 500 ₽', '4 000 ₽', 'Свежий, ягодно-цветочный аромат с лёгкой кислинкой ревеня и сочной ежевикой. В начале звучит ярко и свежо, затем становятся заметны нежные белые цветы и прохладные морские оттенки. В базе становится мягче и чище — появляется мускус, минеральные и слегка амбровые ноты, которые оставляют аккуратный, современный шлейф. Для тех, кто хочет женственный аромат, но не приторно-сладкий, а свежий, ягодный и немного необычный.', 'Шалфей, ревень, ежевика', 'Египетский жасмин, морские ноты, ландыш', 'Минеральные ноты, амбергрис, мускус, ваниль', '', '', true, 'her-02.jpg', 16, true),
  ('her-03', 'Rituals of Anfar Chef-D’Oeuvre', 'Anfar London', 'her', '80 мл', '3 500 ₽', '4 200 ₽', 'Яркий, свежий и немного сладкий цитрусовый аромат с тёплой амброй и мягкой ванилью. Сочный сицилийский апельсин, лимон и бергамот — аромат сразу звучит солнечно и свежо. Через некоторое время цитрусовая свежесть становится мягче, появляются фруктовые и тёплые амбровые оттенки. В финале остаются белый мускус и ваниль, создавая чистый, кремовый и слегка сладковатый шлейф. Для тех, кто хочет свежий аромат, который постепенно становится более тёплым и уютным. Подойдёт и ему, и ей.', 'Сицилийский апельсин, калабрийский бергамот, сицилийский лимон', 'Амбра, фруктовые ноты', 'Белый мускус, мадагаскарская ваниль', '', '', true, 'her-03.jpg', 17, true),
  ('her-04', 'Now Women', 'RAVE', 'her', '100 мл', '2 500 ₽', '', 'Нежный, сладкий и фруктовый аромат с красивым оттенком красных ягод и мягкой ванили. Сочные ягоды и апельсин в самом начале, а затем воздушный маршмеллоу и нежные белые цветы. Постепенно становится более мягким и уютным: остаются ваниль, мускус и лёгкая мшистая нота. Женственный, сладковатый и немного пудровый аромат без ощущения тяжести. Для тех, кто хочет что-то нежное, приятное и заметное на каждый день.', 'Красные ягоды, апельсин', 'Маршмеллоу, ландыш, жасмин', 'Ваниль, мускус, мох', '', '', true, 'her-04.jpg', 18, true),
  ('her-05', 'Now White', 'RAVE', 'her', '100 мл', '2 500 ₽', '', 'Свежий, чистый и лёгкий аромат с ярким цитрусовым началом. Сочный грейпфрут и бергамот — сначала звучит прохладно и свежо, затем становится мягче благодаря зелёному яблоку и пачули. В базе остаются мускус, кашмеран и тёплая амбра, поэтому аромат постепенно становится более мягким и уютным, сохраняя ощущение чистоты и свежести. Для тех, кто хочет универсальный аромат на каждый день, который не перегружает и легко вписывается в любой образ. Подойдёт и ему, и ей.', 'Грейпфрут, бергамот', 'Зелёное яблоко, пачули', 'Мускус, кашмеран, амбра', '', '', true, 'her-05.jpg', 19, true),
  ('her-06', 'Diyana Exclusive', 'Loui Martin', 'her', '80 мл', '2 500 ₽', '', 'Нежный, фруктово-цветочный аромат с сочным личи и лёгкой кислинкой ревеня. В начале звучит свежо и ярко, а затем становится мягче — появляются нежная роза, пион и лёгкая ванильная сладость. Постепенно становится теплее и глубже: к цветам добавляются мягкие древесные и слегка пряные оттенки. Женственный, ухоженный и элегантный аромат с красивым шлейфом. Для тех, кто хочет нежный цветочный аромат, но не слишком простой и не приторно-сладкий.', 'Личи, ревень, бергамот, мускатный орех', 'Турецкая роза, пион, мускус, петалия, ваниль', 'Кашмеран, ладан, кедр, гаитянский ветивер', '', '', true, 'her-06.jpg', 20, true),
  ('her-07', 'Bade’e Al Oud Noble Blush', 'Lattafa', 'her', '100 мл', '3 800 ₽', '', 'Нежный, кремовый и сладковатый аромат с мягким оттенком розы. В начале звучит воздушно и молочно, затем раскрывается сочетанием миндальной сладости и лёгкого безе — ощущение нежного десерта. В базе становится теплее и мягче: ваниль, сандал и мускус создают уютный, бархатистый шлейф. Для тех, кто хочет женственный, мягкий и сладкий аромат без тяжёлой восточной насыщенности.', 'Розовое молоко', 'Безе, миндаль', 'Ваниль, сандал, мускус', '', '', true, 'her-07.jpg', 21, true),
  ('her-08', 'Ameerat Al Arab', 'Asdaaf', 'her', '100 мл', '2 500 ₽', '', 'Свежий, нежный и женственный аромат с лёгкой восточной ноткой. В начале ощущаются яркие цитрусы и бергамот, затем становится мягче — появляются белый мускус и алоэ вера. Постепенно раскрываются жасмин, древесные оттенки и мягкая амбровая теплота. Чистый, ухоженный и слегка восточный аромат — без ощущения тяжёлой сладости. Для тех, кто хочет женственный аромат на каждый день, который звучит аккуратно, свежо и при этом имеет характер.', 'Цитрусы, бергамот', 'Белый мускус, алоэ вера', 'Жасмин, мускус, древесные ноты, уд', '', '', true, 'her-08.jpg', 22, true)
