insert into faq (question, answer, sort_order, is_visible) values
  ('Как понять, какой аромат мне подойдёт?', 'Если вы не знаете, с чего начать, напишите нам в WhatsApp, какие ароматы вам обычно нравятся — свежие, сладкие, древесные, цветочные, пряные или более насыщенные. Мы предложим несколько вариантов из нашей коллекции.', 0, true),
  ('Что делать, если я вообще не знаю, какой аромат выбрать?', 'Ничего страшного. Расскажите, для кого выбираете аромат, какие запахи вам нравятся или, наоборот, какие не любите. Мы поможем подобрать несколько вариантов.', 1, true),
  ('Как заказать аромат?', 'Выберите понравившийся аромат в каталоге и нажмите «Заказать в WhatsApp». После этого мы подтвердим наличие и детали заказа.', 2, true),
  ('Можно ли сначала уточнить наличие?', 'Конечно. Перед оплатой мы подтверждаем наличие выбранного аромата и согласовываем все детали заказа в WhatsApp.', 3, true),
  ('Как происходит оплата?', 'После подтверждения заказа в WhatsApp мы отправляем реквизиты для перевода на карту.', 4, true),
  ('Как осуществляется доставка?', 'Отправляем заказы по всей России. Способ доставки можно выбрать в зависимости от вашего города и удобства.', 5, true),
  ('Можно ли заказать, если я нахожусь в другом городе?', 'Да. Мы отправляем заказы по всей России.', 6, true),
  ('Можно ли спросить совета перед покупкой?', 'Да. Если сомневаетесь между несколькими ароматами, напишите нам — поможем сравнить их и подобрать подходящий вариант.', 7, true),
  ('Как узнать больше об аромате?', 'В карточке каждого аромата указаны его описание, ноты и объём. Если информации недостаточно, напишите нам в WhatsApp.', 8, true)
